def topKFrequent(nums: List[int], k: int) -> List[int]:
    freq = Counter(nums)
    bucket = [[] for _ in range(len(nums) + 1)]
    for x, f in freq.items():
        bucket[f].append(x)
    res = []
    for f in range(len(bucket) - 1, 0, -1):
        for x in bucket[f]:
            if len(res) == k:
                break
            res.append(x)
    return res

